const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (Southern Iberian Peninsula cropland-heavy area: Guadalquivir valley)
    const roi = ee.Geometry.Rectangle([-6.9, 36.7, -3.5, 38.1]); // W, S, E, N
    const start2023 = '2023-03-25';
    const end2023 = '2023-04-23';
    const years = ee.List.sequence(2000, 2010).getInfo();

    // Helper: Build MODIS NDVI collection with QA mask
    function buildModisNdviCol(datasetId, start, end) {
      let col = ee.ImageCollection(datasetId).filterDate(start, end).filterBounds(roi);
      return col.map(function(img) {
        let ndvi = img.select('NDVI').multiply(0.0001);
        let qa = img.select('SummaryQA'); // 0: good, 1: marginal, 2: snow/ice, 3: cloudy
        let mask = qa.lte(1);
        return ndvi.updateMask(mask).rename('NDVI').copyProperties(img, ['system:time_start']);
      });
    }

    // Helper: Fetch collection with fallback
    function getNdviCollectionWithFallback(start, end) {
      let col1 = buildModisNdviCol('MODIS/006/MOD13Q1', start, end);
      let size1 = col1.size();
      return ee.Algorithms.If(size1.gt(0),
        col1,
        buildModisNdviCol('MODIS/006/MOD13A2', start, end)
      );
    }

    // Helper: Compute stats (mean NDVI, valid pixel count, total pixel count)
    function imageStats(img) {
      let mean = img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }).get('NDVI');
      let count = img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }).get('NDVI');
      let total = ee.Image(1).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }).get('constant');
      return ee.Dictionary({mean: mean, count: count, total: total});
    }

    // Helper: Small number formatting
    function fmt(n, d=3) {
      if (n === null || n === undefined || isNaN(n)) return 'null';
      return Number(n).toFixed(d);
    }

    // ROI summary
    const areaKm2 = ee.Number(roi.area()).divide(1e6).getInfo();
    console.log(`ROI area (km^2): ${fmt(areaKm2,1)}`);

    // 2. 2023 period stats with fallback
    let col2023 = ee.ImageCollection(getNdviCollectionWithFallback(start2023, end2023));
    const col2023Size = col2023.size().getInfo();
    if (col2023Size === 0) {
      console.log(`2023 Images: 0`);
      console.log('C1');
      return;
    }
    let img2023 = col2023.mean();
    let stats2023 = imageStats(img2023).getInfo();
    let mean2023 = stats2023.mean;
    let count2023 = stats2023.count || 0;
    let total2023 = stats2023.total || 0;
    let cloudPct2023 = total2023 > 0 ? (100 * (1 - count2023 / total2023)) : null;

    if (!isFinite(count2023) || count2023 === 0) {
      console.log(`2023 Images: ${col2023Size}, ValidPix: 0`);
      console.log('C2');
      return;
    }
    if (mean2023 === null || isNaN(mean2023) || mean2023 < -1 || mean2023 > 1) {
      console.log(`2023 Images: ${col2023Size}, MeanNDVI: ${fmt(mean2023)}, ValidPix: ${count2023}`);
      console.log('C3');
      return;
    }
    console.log(`2023: imgs=${col2023Size}, validPix=${count2023}, cloud%=${fmt(cloudPct2023,1)}, meanNDVI=${fmt(mean2023,3)}`);

    // 3. Long-term (2000-2010) per-year stats
    let ltMeans = [];
    let ltYearsUsed = 0;
    let ltYearsWithImgs = 0;
    for (let i = 0; i < years.length; i++) {
      const y = years[i];
      const s = `${y}-03-25`;
      const e = `${y}-04-23`;
      let colY = ee.ImageCollection(getNdviCollectionWithFallback(s, e));
      let sizeY = colY.size().getInfo();
      if (sizeY === 0) {
        console.log(`${y}: imgs=0`);
        continue;
      }
      ltYearsWithImgs += 1;
      let imgY = colY.mean();
      let statsY = imageStats(imgY).getInfo();
      let meanY = statsY.mean;
      let countY = statsY.count || 0;
      let totalY = statsY.total || 0;
      if (!isFinite(countY) || countY === 0) {
        console.log(`${y}: imgs=${sizeY}, validPix=0`);
        continue;
      }
      if (meanY === null || isNaN(meanY) || meanY < -1 || meanY > 1) {
        console.log(`${y}: imgs=${sizeY}, mean=invalid`);
        continue;
      }
      ltMeans.push(meanY);
      ltYearsUsed += 1;
      console.log(`${y}: imgs=${sizeY}, validPix=${countY}, mean=${fmt(meanY,3)}`);
    }

    if (ltYearsWithImgs === 0) {
      console.log('LT 2000-2010: 0 image-years');
      console.log('C1');
      return;
    }
    if (ltYearsUsed === 0) {
      console.log('LT 2000-2010: images found but 0 valid pixels after masking');
      console.log('C2');
      return;
    }

    const ltMean = ltMeans.reduce((a, b) => a + b, 0) / ltMeans.length;
    if (ltMean === null || isNaN(ltMean) || ltMean < -1 || ltMean > 1) {
      console.log(`LT mean invalid: ${fmt(ltMean)}`);
      console.log('C3');
      return;
    }
    console.log(`LT mean (2000-2010): ${fmt(ltMean,3)}, years used: ${ltYearsUsed}/11`);
    const diff = mean2023 - ltMean;
    console.log(`Diff (2023 - LT): ${fmt(diff,3)}`);

    // 5. Final Answer
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error('Error:', err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
